 ap=argparse.ArgumentParser();ap.add_argument('--out',required=True,type=Path);a=ap.parse_args();a.out.mkdir(exist_ok=False,parents=True);(a.out/'proofs').mkdir();p=ROOT/'results/tube_evidence_20261003/replay';oldrows=json.loads((p/'warm.json').read_bytes());selected=[w for w in oldrows if (w['radius_um'],w['sigma']) in [(0,0.),(5000,.001),(50000,.01)]];assert len(selected)==36;sources={s['case']:s for s in json.loads((ROOT/'results/pose_inversion_20261003/replay/sources.json').read_bytes())};bps=sorted({s['blueprint'] for s in sources.values()});analysispath=ROOT/'results/terrain_score_20261003/analysis_sheng.json';digest=hashlib.sha256(analysispath.read_bytes()).hexdigest();analysis=json.loads(analysispath.read_bytes());so='/tmp/mobi_adaptive_repair.so';cmd=['c++','-O3','-std=c++17','-ffp-contract=off','-shared','-fPIC',str(HERE/'adaptive.cpp'),'-o',so];subprocess.run(cmd,check=True);lib=library(so);rows=[]
 for w in selected:
  source=sources[w['old_case']];reference_name=next(c['reference'] for c in json.loads((p/'cold.json').read_bytes()) if c['proof']==w['proof']);reference=zlib.decompress((p/reference_name).read_bytes());current=zlib.decompress((p/w['current_packet']).read_bytes());archived=(p/w['message']).read_bytes();z=np.load(p/w['proof']);tree={k:z[k] for k in z.files};proof=Proof(lib,reference,digest,bps,source,(-6 if w['query_index']==0 else 6,0),analysis['summary'][w['blueprint']]['threshold'],w['radius_um'],tree);proof.saved_tree=tree
  for rep in range(3):
   begin=time.perf_counter();wire=encode(current,reference,w['radius_um'],digest,bps);enc=time.perf_counter()-begin;assert wire==archived;external=240000+len(wire)*.4+w['packet_encode_s']*1e6+enc*1e6;r=repaired(proof,wire,external);lower,upper=map(int,r['stat'][:2]);name='proofs/'+Path(w['message']).stem+'_r'+str(rep)+'.npz';np.savez_compressed(a.out/name,**{k:r[k] for k in ('cells','meta','counts','flags','witness')});row={k:w[k] for k in ('blueprint','query_index','radius_um','sigma','old_case','current_case','current_packet','proof','output','message','wire_bytes','packet_encode_s','source_timestamp','source_frame')};row.update(repeat=rep,budget=4096,repair_output=name,repair_sha256=hashlib.sha256((a.out/name).read_bytes()).hexdigest(),nodes=len(r['cells']),baseline_lower_us=w['lower_us'],lower_us=lower,upper_us=upper,gap_us=upper-lower,visits=int(r['stat'][4]),new_bound_calls=int(r['stat'][5]),witness_calls=int(r['stat'][6]),has_witness=bool(r['stat'][7]),restore_s=proof.restore_s,encode_s=enc,receiver_s=r['receiver_s'],baseline_s=r['baseline_s'],external_us=external,gate=r['gate'].tolist(),remaining_us=max(0,lower-math.ceil(external+r['receiver_s']*1e6)),baseline_remaining_us=max(0,w['lower_us']-math.ceil(external+r['baseline_s']*1e6)));rows.append(row);print(json.dumps({k:row[k] for k in ('blueprint','query_index','radius_um','repeat','visits','remaining_us','baseline_remaining_us','gate')}),flush=True)
  proof.close()
 (a.out/'rows.json').write_text(json.dumps(rows,indent=2)+'\n');files=[HERE/f for f in ('adaptive.cpp','adaptive_runtime.py','run_adaptive.py','ADAPTIVE_PROTOCOL.md','kernel.cpp','repair_runtime.py')]+[ROOT/'experiments/tube_evidence_20261003'/f for f in ('kernel.cpp','runtime.py','codec.py')]+[ROOT/'experiments/expiry_runtime_20261003/kernel.cpp'];(a.out/'manifest.json').write_text(json.dumps(dict(rows=len(rows),command=cmd,prior_artifact_manifest_sha256=hashlib.sha256((p.parent/'artifact_manifest.json').read_bytes()).hexdigest(),source_hashes={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest() for f in files}),indent=2)+'\n')
